/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void clicked()
{
    FormRun                 formRun;
    FormDataSource          dirPartyRelationshipDS;

    formRun                 = this.formRun();
    dirPartyRelationshipDS  = formRun.dataSource('DirPartyRelationship');
    dirPartyRelationshipDS.create();

